-- ── 1a. Quirófano y Anestesiología (PR-QX + PR-CEYE) ─────────────
UPDATE risk_processes SET
  process_owner = 'Jefe de Quirófano / Jefatura de Enfermería',
  description   = 'Realización de procedimientos quirúrgicos, manejo anestésico y gestión de central de equipos y esterilización (CEYE).',
  risks = '[
    {"id":"qx-01","type":"riesgo","description":"Mala ejecución de la técnica anestésica (ASC 3.2)","cause":"Error en la técnica por parte del anestesiólogo o condiciones del paciente","effect":"Complicaciones graves, riesgo de muerte del paciente","probability":2,"impact":5,"action_plan":"Cumplir con la Normativa. Realizar valoración preanestésica completa antes de cada procedimiento.","responsible":"Médico Anestesiólogo","due_date":"2025-12-31","status":"en_control"},
    {"id":"qx-02","type":"riesgo","description":"Estado general del paciente con complicaciones no previstas en cirugía","cause":"Valoración preanestésica insuficiente o incompleta","effect":"Complicaciones intraoperatorias, prolongación del procedimiento, riesgo de muerte","probability":3,"impact":4,"action_plan":"Realizar valoración preanestésica completa. Cumplir con la Normativa vigente.","responsible":"Médico Anestesiólogo","due_date":"2025-12-31","status":"en_control"},
    {"id":"qx-03","type":"riesgo","description":"Uso de ropa quirúrgica sucia en área de quirófano","cause":"Error en el flujo de transfer, mal etiquetado de bultos","effect":"Contaminación cruzada, infección del sitio quirúrgico","probability":1,"impact":5,"action_plan":"Estandarización del etiquetado de bultos para identificar los sucios de los limpios. Revisión del registro del operador de GPH.","responsible":"Jefe de Quirófano","due_date":"2025-11-30","status":"en_control"},
    {"id":"qx-04","type":"riesgo","description":"Lesión del operativo al juntar instrumental corto-punzante con el bulto","cause":"Manejo inadecuado y desecho sin precaución del material corto-punzante","effect":"Accidente laboral, exposición a riesgo biológico","probability":3,"impact":3,"action_plan":"Manejo, utilización y desecho del material corto-punzante con extremado cuidado. Capacitación al personal.","responsible":"Jefe de Quirófano","due_date":"2025-11-30","status":"en_control"},
    {"id":"qx-05","type":"riesgo","description":"Contaminación de área blanca por no reemplazar accesorios dañados (CEYE)","cause":"Falta de supervisión del estado de los accesorios de ingreso a quirófano","effect":"Contaminación del área estéril, riesgo de IAAS","probability":2,"impact":3,"action_plan":"Supervisar el cambio de accesorios por daño o contaminación.","responsible":"Jefe de Quirófano","due_date":"2025-12-31","status":"en_control"},
    {"id":"qx-06","type":"riesgo","description":"Infecciones cruzadas por no cambiar uniforme quirúrgico contaminado (CEYE)","cause":"Incumplimiento del protocolo de cambio de uniforme tras cirugía contaminada","effect":"Contaminación del área quirúrgica, riesgo de IAAS","probability":2,"impact":4,"action_plan":"Capacitar sobre la correcta manera de portar uniforme quirúrgico. Supervisión del cumplimiento.","responsible":"Jefe de Quirófano","due_date":"2025-11-30","status":"en_control"},
    {"id":"qx-07","type":"riesgo","description":"Lavado inadecuado del instrumental quirúrgico (CEYE)","cause":"Omisión de actividades durante el lavado, técnica incorrecta","effect":"Esterilización deficiente, riesgo de infección del sitio quirúrgico","probability":2,"impact":4,"action_plan":"Reforzar el proceso correcto para lavado de material. Poner especial cuidado al sumergir, sacar, tallar y secar instrumental afilado.","responsible":"Jefe de CEYE","due_date":"2025-11-30","status":"en_control"},
    {"id":"qx-08","type":"riesgo","description":"Omisión o manejo inadecuado del proceso de esterilización (CEYE)","cause":"Incumplimiento de la bitácora de mantenimiento de autoclaves","effect":"Material no estéril utilizado en procedimientos, infección grave del paciente","probability":2,"impact":4,"action_plan":"Cumplir con la bitácora de mantenimiento de las autoclaves. No exceder la capacidad de la autoclave. Respetar los tiempos de esterilización.","responsible":"Jefe de CEYE","due_date":"2025-11-30","status":"en_control"},
    {"id":"qx-09","type":"riesgo","description":"Salida de bultos mojados por no respetar tiempos de esterilización o capacidad de la autoclave","cause":"Sobrecarga de la autoclave o tiempos insuficientes de secado","effect":"Material considerado contaminado, retraso en cirugías, riesgo de infección","probability":2,"impact":4,"action_plan":"No exceder la capacidad de la autoclave. Respetar los tiempos de esterilización y secado.","responsible":"Jefe de CEYE","due_date":"2025-11-30","status":"en_control"}
  ]',
  updated_at = now()
WHERE name = 'Quirófano y Anestesiología';

-- ── 1b. Imagenología y Diagnóstico (PR-RX) ───────────────────────
UPDATE risk_processes SET
  process_owner = 'Jefe de Imagenología / Radiología',
  description   = 'Estudios de diagnóstico por imagen: estudios contrastados, radiografías simples (hospitalización y externos) con y sin condición COVID.',
  risks = '[
    {"id":"rx-01","type":"riesgo","description":"Registro erróneo del paciente (nombre, edad, estudio solicitado) al inicio del proceso","cause":"Falta de verificación de datos antes de finalizar el registro en el sistema","effect":"Estudio realizado a paciente equivocado, error diagnóstico, responsabilidad médico-legal","probability":3,"impact":3,"action_plan":"Corroborar los datos del paciente antes de finalizar el registro en el sistema. Doble verificación en recepción.","responsible":"Jefe de Imagenología","due_date":"2025-11-30","status":"en_control"},
    {"id":"rx-02","type":"riesgo","description":"Errores técnicos en la realización del estudio (radiología o contrastados)","cause":"Falta de verificación del registro correcto antes de iniciar el estudio","effect":"Estudio no útil diagnósticamente, necesidad de repetir con exposición adicional al paciente","probability":2,"impact":3,"action_plan":"Corroborar con el paciente el registro correcto de los datos antes de finalizar el registro en el equipo de rayos X.","responsible":"Jefe de Imagenología","due_date":"2025-11-30","status":"en_control"},
    {"id":"rx-03","type":"riesgo","description":"Entrega errónea de estudios al paciente incorrecto","cause":"Falta de verificación de datos antes de entregar el estudio en CD","effect":"Entrega de resultados a paciente equivocado, confidencialidad comprometida, error diagnóstico","probability":2,"impact":4,"action_plan":"Verificar datos del paciente antes de entregar el estudio en CD. Confirmar la lectura y firma del consentimiento informado.","responsible":"Jefe de Imagenología","due_date":"2025-11-30","status":"en_control"},
    {"id":"rx-04","type":"riesgo","description":"Efectos secundarios al medio de contraste empleado en el estudio","cause":"Reacción alérgica o adversa al medio de contraste intravenoso","effect":"Reacción anafiláctica, daño renal, evento adverso grave","probability":2,"impact":5,"action_plan":"Confirmar la lectura y firma del consentimiento informado por parte del paciente o familiar. Tener protocolo de manejo de reacciones al contraste disponible.","responsible":"Médico Radiólogo","due_date":"2025-11-30","status":"en_control"},
    {"id":"rx-05","type":"riesgo","description":"Error en el registro de correo electrónico o número de celular para envío de estudios","cause":"Datos de contacto incorrectos o incompletos al momento del registro","effect":"El paciente no recibe sus resultados, retraso diagnóstico","probability":2,"impact":2,"action_plan":"Corroborar el correo electrónico y/o número de celular antes de despedir al paciente.","responsible":"Jefe de Imagenología","due_date":"2025-12-31","status":"en_control"},
    {"id":"rx-06","type":"riesgo","description":"Cobro erróneo de los estudios contrastados solicitados (urgencias)","cause":"Falta de verificación de los estudios facturados vs los realizados","effect":"Pérdida de ingresos, inconformidad del paciente, problemas de facturación","probability":3,"impact":2,"action_plan":"Confirmar con el paciente la correcta identificación antes de realizar el estudio. Revisión de cobros generados vs estudios realizados.","responsible":"Jefe de Imagenología","due_date":"2025-12-31","status":"identificado"}
  ]',
  updated_at = now()
WHERE name = 'Imagenología y Diagnóstico';

-- ── 1c. Farmacia y Suministro de Medicamentos (PR-FH) ─────────────
UPDATE risk_processes SET
  process_owner = 'Jefe de Farmacia Hospitalaria',
  description   = 'Conciliación de medicamentos, dispensación, prescripción segura, uso seguro de medicamentos multidosis, identificación de cuasifallas y monitorización de medicamentos en cuadro básico.',
  risks = '[
    {"id":"fh-01","type":"riesgo","description":"Recabar información incompleta o incorrecta de los medicamentos que toma el paciente en casa (PR-FH-01)","cause":"Habilidades de comunicación insuficientes del farmacéutico, datos incompletos en el expediente","effect":"Conciliación incorrecta, duplicidad o interacciones medicamentosas no detectadas","probability":3,"impact":3,"action_plan":"Desarrollar y perfeccionar las habilidades de comunicación de los farmacéuticos. Contar con la plantilla completa y capacitada.","responsible":"Jefe de Farmacia","due_date":"2025-11-30","status":"en_control"},
    {"id":"fh-02","type":"riesgo","description":"Conciliación de medicamentos al ingreso realizada pasadas las 4 horas (PR-FH-01)","cause":"Carga de trabajo excesiva, priorización incorrecta de actividades","effect":"Decisiones clínicas sin información completa de medicación domiciliaria","probability":2,"impact":3,"action_plan":"Contar con la plantilla de farmacéuticos completa y capacitada para realizar la conciliación de la medicación en tiempo.","responsible":"Jefe de Farmacia","due_date":"2025-11-30","status":"en_control"},
    {"id":"fh-03","type":"riesgo","description":"Errores de medicación derivados de malas prácticas en la prescripción (PR-FH-03)","cause":"Prescripción incompleta, ilegible o con abreviaturas peligrosas","effect":"Evento adverso medicamentoso, daño al paciente","probability":3,"impact":4,"action_plan":"Revisión, evaluación, detección y comunicación oportuna y efectiva al Médico Tratante de errores potenciales en la prescripción.","responsible":"Jefe de Farmacia","due_date":"2025-11-15","status":"en_control"},
    {"id":"fh-04","type":"riesgo","description":"Errores de medicación derivados de malas prácticas en la transcripción de indicaciones médicas (PR-FH-04)","cause":"Transcripción incorrecta de indicaciones, letra ilegible, indicación incompleta","effect":"Administración de medicamento erróneo o dosis incorrecta","probability":3,"impact":4,"action_plan":"Revisión, evaluación, detección y comunicación oportuna y efectiva al Médico de Guardia de errores potenciales en la transcripción. Aclarar oportunamente cualquier duda, error y/o indicación incompleta.","responsible":"Jefe de Farmacia","due_date":"2025-11-15","status":"en_control"},
    {"id":"fh-05","type":"riesgo","description":"Riesgo a la salud del paciente derivado de un PRM o RNM no atendido (PR-FH-05)","cause":"Falta de identificación oportuna de problemas relacionados con medicamentos","effect":"Daño al paciente, evento adverso grave","probability":2,"impact":5,"action_plan":"Personal farmacéutico capacitado con competencias para identificar PRM y RNM. Intervención farmacéutica adecuada y asertiva.","responsible":"Jefe de Farmacia","due_date":"2025-11-30","status":"en_control"},
    {"id":"fh-06","type":"riesgo","description":"Contaminación microbiológica de medicamentos multidosis por compartirlos entre pacientes o usar agujas no estériles (PR-FH-06)","cause":"Incumplimiento del protocolo de uso de medicamentos multidosis","effect":"Infección al paciente asociada a la atención sanitaria","probability":2,"impact":4,"action_plan":"Manipular correctamente los medicamentos multidosis. Realizar los Correctos de Enfermería y cumplir con la Meta Internacional de Seguridad del Paciente 6 (MISP.6).","responsible":"Jefe de Farmacia","due_date":"2025-11-30","status":"en_control"},
    {"id":"fh-07","type":"riesgo","description":"Cultura organizacional punitiva que no favorece la comunicación de cuasifallas y errores de medicación (PR-FH-08)","cause":"Miedo a consecuencias disciplinarias, falta de cultura de seguridad","effect":"Errores no notificados, pérdida de oportunidad de aprendizaje y mejora","probability":3,"impact":3,"action_plan":"Analizar el error sin considerar a quien intervino, para identificar cómo y por qué se ha producido. Mejorar la cultura organizacional para incrementar la notificación.","responsible":"Director General","due_date":"2026-01-31","status":"identificado"},
    {"id":"fh-08","type":"riesgo","description":"Inefectividad o inseguridad del medicamento recién agregado al cuadro básico (PR-FH-09)","cause":"Vigilancia insuficiente de la respuesta del paciente a medicamentos nuevos","effect":"Daño al paciente, necesidad de retiro urgente del medicamento del cuadro básico","probability":2,"impact":4,"action_plan":"Contar con profesionales de la salud formados para detectar si el medicamento está consiguiendo el objetivo terapéutico. Análisis de errores y establecimiento de estrategias para disminuirlos.","responsible":"Jefe de Farmacia","due_date":"2025-12-31","status":"identificado"},
    {"id":"fh-09","type":"riesgo","description":"Duplicidad en la administración de medicamento del paciente (PR-FH-02)","cause":"Falta de conciliación al ingreso y cambios de médico tratante","effect":"Sobredosis, intoxicación, riesgo para la salud del paciente","probability":2,"impact":4,"action_plan":"Realizar de manera oportuna y efectiva la conciliación de la medicación al ingreso.","responsible":"Jefe de Farmacia","due_date":"2025-11-30","status":"en_control"}
  ]',
  updated_at = now()
WHERE name = 'Farmacia y Suministro de Medicamentos';

-- ── 1d. Limpieza y Gestión Ambiental (PR-IN + PR-SG) ─────────────
