  process_owner = 'Jefe de Servicios Generales / Intendencia',
  description   = 'Aseo tipo cultivo, aseo exhaustivo supervisado y nebulizado, limpieza y desinfección de quirófano, manejo de RPBI, productos químicos, recolección de residuos peligrosos y fumigación.',
  risks = '[
    {"id":"in-01","type":"riesgo","description":"Salas quirúrgicas en condiciones antihigiénicas por limpieza y desinfección insuficiente (PR-IN-03)","cause":"Personal sin capacitación en técnicas de limpieza de áreas críticas","effect":"Riesgo de infecciones hospitalarias, contaminación del área quirúrgica","probability":2,"impact":4,"action_plan":"Capacitación al personal sobre las técnicas de limpieza en las distintas áreas. Supervisión continua con listas de verificación.","responsible":"Jefe de Intendencia","due_date":"2025-11-30","status":"en_control"},
    {"id":"in-02","type":"riesgo","description":"Riesgos a la salud del personal por exposición a agentes biológicos en área de quirófano (PR-IN-03)","cause":"Manejo inadecuado de materiales biológicos, falta de EPP","effect":"Accidente laboral, contagio de enfermedades infecciosas","probability":3,"impact":4,"action_plan":"Uso de equipo de protección personal. Capacitación en manejo adecuado de RPBI.","responsible":"Jefe de Intendencia","due_date":"2025-11-30","status":"en_control"},
    {"id":"in-03","type":"riesgo","description":"Clasificación y separación errónea de Residuos Peligrosos Biológico-Infecciosos (RPBI) (PR-SG-07)","cause":"Personal no capacitado en identificación y separación de RPBI","effect":"Sanciones administrativas, contaminación cruzada, riesgo biológico","probability":3,"impact":4,"action_plan":"Capacitación para la identificación, separación y envasado de RPBI. Supervisión de contenedores de RPBI en cada área.","responsible":"Jefe de Servicios Generales","due_date":"2025-11-30","status":"en_control"},
    {"id":"in-04","type":"riesgo","description":"Contaminación y daño a la salud por manipulación inadecuada de RPBI (PR-SG-07)","cause":"Manejo incorrecto de residuos biológico-infecciosos, falta de EPP adecuado","effect":"Riesgo biológico para personal y pacientes, sanciones COFEPRIS/SEMARNAT","probability":3,"impact":4,"action_plan":"Capacitar al personal para el manejo adecuado de RPBI y el uso correcto del equipo de protección personal.","responsible":"Jefe de Servicios Generales","due_date":"2025-11-30","status":"en_control"},
    {"id":"in-05","type":"riesgo","description":"Accidentes de trabajo por mal manejo y almacenamiento de productos químicos (PR-SG-06)","cause":"Falta de capacitación en manejo de químicos, ausencia de hojas de datos de seguridad","effect":"Intoxicación, irritación cutánea, riesgo ambiental","probability":3,"impact":4,"action_plan":"Capacitar al personal para el manejo adecuado de productos químicos. Existencia de las hojas de datos de seguridad de cada sustancia en cada área.","responsible":"Jefe de Servicios Generales","due_date":"2025-11-30","status":"en_control"},
    {"id":"in-06","type":"riesgo","description":"Contaminación por agentes patógenos en el agua por niveles de cloro inadecuados (PR-SG-08/21)","cause":"Falta de monitoreo frecuente de niveles de cloro residual","effect":"Riesgo de enfermedades transmitidas por el agua, sanciones sanitarias","probability":2,"impact":4,"action_plan":"Monitoreo frecuente de los niveles de cloro residual en el agua. Medidas correctivas y control constante hasta tener los parámetros óptimos. Documentación de bitácoras mensuales.","responsible":"Jefe de Servicios Generales","due_date":"2025-11-30","status":"en_control"},
    {"id":"in-07","type":"riesgo","description":"Mal manejo de traslado y almacenamiento de residuos peligrosos (PR-SG-14)","cause":"Personal no capacitado, incumplimiento de procedimientos de traslado","effect":"Sanciones de autoridades competentes, riesgo ambiental y de salud","probability":3,"impact":4,"action_plan":"Capacitar al personal para el manejo adecuado de residuos peligrosos y uso del equipo de protección. Control administrativo en base a bitácoras.","responsible":"Jefe de Servicios Generales","due_date":"2025-11-30","status":"en_control"},
    {"id":"in-08","type":"riesgo","description":"Generación de plagas por fauna nociva en áreas del hospital (PR-SG-20)","cause":"Control de fumigación insuficiente o irregular","effect":"Riesgo de contaminación, sanciones sanitarias, daño a la imagen institucional","probability":2,"impact":3,"action_plan":"Control de fumigación mensual y atención a las incidencias en su momento. Tomar medidas preventivas para la fumigación del área con el equipo adecuado.","responsible":"Jefe de Servicios Generales","due_date":"2025-12-31","status":"en_control"}
  ]',
  updated_at = now()
WHERE name = 'Limpieza y Gestión Ambiental';

-- ── 1e. Mantenimiento de Infraestructura y Equipos (PR-SG) ────────
