  process_owner = 'Jefe de Mantenimiento / Servicios Generales',
  description   = 'Mantenimiento correctivo y preventivo de equipos e infraestructura, mantenimiento preventivo externo, supervisión en construcción y remodelación, monitoreo de servicios básicos y gestión de la planta de energía eléctrica.',
  risks = '[
    {"id":"sg-01","type":"riesgo","description":"Accidentes de trabajo durante mantenimiento correctivo de equipos o infraestructura (PR-SG-04)","cause":"Falta de uso de equipo de protección personal adecuado a la actividad","effect":"Lesiones al personal, ausentismo, responsabilidad legal","probability":3,"impact":4,"action_plan":"Usar el equipo de protección personal correspondiente a la actividad que se ejecutará. Capacitación en seguridad laboral.","responsible":"Jefe de Mantenimiento","due_date":"2025-11-30","status":"en_control"},
    {"id":"sg-02","type":"riesgo","description":"Deterioro de equipos o áreas requiriendo mantenimiento correctivo con presupuesto alto (PR-SG-05)","cause":"Falta de programa de mantenimiento preventivo o incumplimiento del mismo","effect":"Costos elevados de reparación, interrupción de servicios","probability":3,"impact":3,"action_plan":"Supervisión del correcto mantenimiento preventivo a equipos y áreas. Programa anual de mantenimiento preventivo.","responsible":"Jefe de Mantenimiento","due_date":"2025-12-31","status":"en_control"},
    {"id":"sg-03","type":"riesgo","description":"Riesgos eléctricos durante mantenimiento: shock eléctrico, quemaduras (PR-SG-09)","cause":"Falta de uso de equipo de protección personal eléctrico","effect":"Accidente laboral grave, quemaduras, electrocución","probability":2,"impact":4,"action_plan":"Uso de equipo de protección personal: guantes y calzado de seguridad. Capacitación en precauciones y técnicas de trabajo eléctrico.","responsible":"Jefe de Mantenimiento","due_date":"2025-11-30","status":"en_control"},
    {"id":"sg-04","type":"riesgo","description":"No activarse algún detector de humo en caso de incidencia (PR-SG-10)","cause":"Falta de revisión mensual de detectores de humo","effect":"Multas por omisión de revisión, riesgo de no detectar incendios oportunamente","probability":2,"impact":4,"action_plan":"Revisión mensual de cada detector de humo. Llevar y resguardar el registro de las bitácoras de revisión.","responsible":"Jefe de Mantenimiento","due_date":"2025-11-15","status":"en_control"},
    {"id":"sg-05","type":"riesgo","description":"Desabasto de gases medicinales (oxígeno, nitrógeno) en el hospital (PR-SG-11)","cause":"Falta de monitoreo diario del stock de gas medicinal","effect":"Interrupción de atención a pacientes críticos, riesgo de muerte","probability":2,"impact":5,"action_plan":"Conteo diario del stock de gas medicinal. Coordinación oportuna con el proveedor para resurtido.","responsible":"Jefe de Mantenimiento","due_date":"2025-11-15","status":"en_control"},
    {"id":"sg-06","type":"riesgo","description":"Desabasto de agua en el hospital (PR-SG-11)","cause":"Falta de control diario de niveles de agua en cisternas","effect":"Interrupción de servicios clínicos y sanitarios, riesgo de IAAS","probability":3,"impact":4,"action_plan":"Control diario de niveles de agua en cisternas. Monitoreo rutinario del consumo diario de agua.","responsible":"Jefe de Mantenimiento","due_date":"2025-11-30","status":"en_control"},
    {"id":"sg-07","type":"riesgo","description":"Falla en la planta de energía eléctrica del hospital (PR-SG-22)","cause":"Falta de mantenimiento preventivo anual o monitoreo diario de la planta","effect":"Interrupción de quirófano, UCI y laboratorio — riesgo de muerte de pacientes","probability":2,"impact":5,"action_plan":"Ejecución de mantenimiento preventivo anual y monitoreo diario de las condiciones de la planta de energía eléctrica.","responsible":"Jefe de Mantenimiento","due_date":"2025-11-15","status":"en_control"},
    {"id":"sg-08","type":"riesgo","description":"No cumplir con la normativa de las autoridades competentes en construcción y remodelación (PR-SG-16)","cause":"Contratación de empresa sin las certificaciones requeridas","effect":"Sanciones de autoridades, suspensión de obra, multas","probability":2,"impact":4,"action_plan":"Certificados de capacitación presentados por la empresa seleccionada. Exámenes toxicológicos presentados por la empresa contratada.","responsible":"Jefe de Mantenimiento","due_date":"2025-12-31","status":"identificado"},
    {"id":"sg-09","type":"riesgo","description":"Contratar prestadores de servicios de baja calidad o con desempeño no confiable (PR-SG-24)","cause":"Falta de proceso de evaluación de prestadores de servicio","effect":"Servicios deficientes, riesgo de daños a equipos o instalaciones","probability":2,"impact":4,"action_plan":"Considerar prestadores de servicios con referencias, renombrados y buen historial. Realizar un análisis de criterios en la evaluación.","responsible":"Administración","due_date":"2025-12-31","status":"identificado"}
  ]',
