-- ── 1f. Recursos Humanos y Capacitación (PR-CH) ───────────────────
UPDATE risk_processes SET
  process_owner = 'Jefatura de Capital Humano',
  description   = 'Reclutamiento, selección y contratación de personal (S.Q.E.6), inducción, capacitación y desarrollo del capital humano del hospital.',
  risks = '[
    {"id":"ch-01","type":"riesgo","description":"Tomar la entrevista como único filtro para la contratación de personal (PR-CH-01)","cause":"Proceso de selección simplificado sin evaluaciones complementarias","effect":"Contratación de personal no competente, riesgos en la calidad de atención y seguridad del paciente","probability":3,"impact":4,"action_plan":"Se emplea herramienta de evaluación de conocimientos, psicométrica y prácticos como filtros adicionales a la entrevista.","responsible":"Jefatura Capital Humano","due_date":"2025-12-31","status":"en_control"},
    {"id":"ch-02","type":"riesgo","description":"Contratar candidato con documentación apócrifa (cédula, título, certificados) (PR-CH-01)","cause":"Verificación insuficiente de la autenticidad de documentos habilitantes","effect":"Personal sin habilitación legal ejerciendo, responsabilidad institucional, sanciones","probability":2,"impact":4,"action_plan":"Validación de documentación por medio de medios electrónicos (RENIECYT, SSP, SEP). Verificación de cédulas profesionales en RENAP.","responsible":"Jefatura Capital Humano","due_date":"2025-12-31","status":"en_control"},
    {"id":"ch-03","type":"riesgo","description":"Candidato que proporciona información falsa sobre anteriores empleos (PR-CH-01)","cause":"Falta de verificación de referencias laborales directamente con empleadores anteriores","effect":"Contratación de personal con antecedentes negativos o incompetente","probability":2,"impact":4,"action_plan":"Solicitar referencia en sus anteriores trabajos, teniendo contacto directamente con la empresa anterior.","responsible":"Jefatura Capital Humano","due_date":"2025-12-31","status":"en_control"},
    {"id":"ch-04","type":"riesgo","description":"Alta rotación de personal clave en áreas críticas","cause":"Condiciones laborales o salariales no competitivas con el mercado","effect":"Pérdida de conocimiento, impacto en calidad de atención, costos de reclutamiento elevados","probability":3,"impact":4,"action_plan":"Encuesta de clima laboral anual. Plan de retención para personal clave. Análisis de salarios vs mercado.","responsible":"Jefatura Capital Humano","due_date":"2026-01-31","status":"identificado"},
    {"id":"ch-05","type":"oportunidad","description":"Programa de desarrollo de competencias alineado al SGC para cerrar brechas de capacitación","cause":"Identificación de necesidades de capacitación a través del SGC","effect":"Personal más competente, menor incidencia de no conformidades por factor humano","probability":4,"impact":4,"action_plan":"Plan anual de capacitación basado en análisis de brechas. Incluir ISO 9001, seguridad del paciente y habilidades técnicas.","responsible":"Jefatura Capital Humano","due_date":"2026-01-31","status":"identificado"}
  ]',
  updated_at = now()
WHERE name = 'Recursos Humanos y Capacitación';


