-- ── 2a. Prevención y Control de Infecciones (UVEH) ───────────────
('Prevención y Control de Infecciones (UVEH)', 'misional',
 'Responsable de Epidemiología / Comité de Infecciones',
 'Vigilancia epidemiológica hospitalaria, control de IAAS, aislamiento de pacientes infecciosos e inmunodeprimidos, medidas de precaución estándar, manejo de RPBI clínico, manejo adecuado de alimentos, construcciones y medicación (PCI).',
 16,
'[
  {"id":"uv-01","type":"riesgo","description":"No realizar seguimiento a la realización del proceso de lavado de manos (PR-UV-08)","cause":"Falta de fechas específicas de capacitación y evaluación del proceso de lavado de manos","effect":"Incumplimiento de la higiene de manos OMS, incremento del riesgo de IAAS","probability":3,"impact":3,"action_plan":"Programar fechas específicas de capacitación y de evaluación de seguimiento del proceso de lavado de manos.","responsible":"Responsable UVEH","due_date":"2025-11-30","status":"en_control"},
  {"id":"uv-02","type":"riesgo","description":"Accidentes laborales por riesgos biológicos (punzocortante) — falta de protocolo de seguimiento (PR-UV-09)","cause":"No conocer el protocolo de seguimiento en caso de accidente laboral por punzocortante / no notificar en tiempo y forma","effect":"Manejo inapropiado del accidente, riesgo de transmisión de enfermedades infecciosas al trabajador","probability":2,"impact":4,"action_plan":"Explicar claramente el proceso a los colaboradores para brindar la atención oportuna.","responsible":"Responsable UVEH","due_date":"2025-11-30","status":"en_control"},
  {"id":"uv-03","type":"riesgo","description":"No apego por parte de los colaboradores a las indicaciones del comité ante alerta epidemiológica (PR-UV-10)","cause":"Desconocimiento de nuevos procesos, incumplimiento de indicaciones del comité","effect":"Propagación de brotes epidémicos, incumplimiento normativo","probability":3,"impact":4,"action_plan":"Estricto apoyo de cada departamento para el cumplimiento de objetivos del comité. Constante capacitación sobre nuevos procesos.","responsible":"Responsable UVEH","due_date":"2025-11-30","status":"en_control"},
  {"id":"uv-04","type":"riesgo","description":"Personal clínico no respeta las medidas de aislamiento para pacientes infecciosos (PR-UV-11)","cause":"Incumplimiento de medidas establecidas, falta de insumos adecuados para el aislamiento","effect":"Transmisión de enfermedades infecciosas a otros pacientes y al personal","probability":3,"impact":4,"action_plan":"Capacitación continua sobre la importancia de las medidas precautorias. Garantizar abastecimiento constante de insumos.","responsible":"Responsable UVEH","due_date":"2025-11-30","status":"en_control"},
  {"id":"uv-05","type":"riesgo","description":"Personal no respeta las precauciones estándar para pacientes inmunodeprimidos (PR-UV-12)","cause":"Incumplimiento de lo establecido en el documento, falta de insumos para el aislamiento","effect":"Infecciones en pacientes inmunodeprimidos, complicaciones graves","probability":3,"impact":4,"action_plan":"Capacitación continua sobre la importancia de las precauciones estándar. Garantizar abastecimiento constante de insumos.","responsible":"Responsable UVEH","due_date":"2025-11-30","status":"en_control"},
  {"id":"uv-06","type":"riesgo","description":"Incidencia recurrente de IAAS y riesgos laborales por falta de insumos de protección (PCI.3)","cause":"Falta de identificación oportuna de IAAS, insumos insuficientes para protección de colaboradores","effect":"Deterioro de la salud de pacientes y personal, mayor estancia hospitalaria, costos elevados","probability":3,"impact":4,"action_plan":"Identificación oportuna de IAAS para aplicar medidas preventivas. Monitoreo frecuente de los insumos necesarios para la atención sanitaria.","responsible":"Responsable UVEH","due_date":"2025-11-30","status":"en_control"},
  {"id":"uv-07","type":"riesgo","description":"Aumento de IAAS e identificación tardía / sanciones COPRISIAL por incumplimiento compromisos CODECIN (PCI.4)","cause":"Capacitación continua insuficiente, adiestramiento deficiente en epidemiología, incumplimiento de compromisos","effect":"Daño a pacientes, sanciones administrativas de COPRISIAL/CODECIN","probability":3,"impact":5,"action_plan":"Capacitación continua al personal clínico sobre acciones de prevención y control de infecciones. Adiestramiento del personal de epidemiología. Compromiso de jefes de departamento en implementación de acciones preventivas.","responsible":"Responsable UVEH","due_date":"2025-11-15","status":"en_control"},
  {"id":"uv-08","type":"riesgo","description":"Brote de infecciones por incumplimiento del protocolo de medidas de precaución estándar (PCI.5 / PR-UV-15)","cause":"Resistencia del personal al uso adecuado de EPP, falta de insumos y equipo de protección","effect":"Brote de enfermedades infectocontagiosas, riesgo de inmunodefresión","probability":2,"impact":5,"action_plan":"Supervisión constante de los procesos en pacientes con enfermedades infectocontagiosas. Capacitación continua del personal clínico. Inventario constante por parte de Farmacia para garantizar disponibilidad de insumos.","responsible":"Responsable UVEH","due_date":"2025-11-15","status":"en_control"},
  {"id":"uv-09","type":"riesgo","description":"Riesgo de infecciones en pacientes por construcciones, remodelaciones y obras (PCI.11 / PR-UV-18)","cause":"Exposición a polvo y humedad por obras, incumplimiento de normativas de STyPS, SEMARNAT, Bomberos, COPRISIAL","effect":"Infecciones respiratorias en pacientes y personal, sanciones por múltiples dependencias","probability":3,"impact":4,"action_plan":"Realización de análisis de riesgo antes del inicio de cualquier construcción o remodelación. Supervisión continua sobre la correcta aplicación de los procesos internos.","responsible":"Responsable UVEH","due_date":"2025-12-31","status":"identificado"},
  {"id":"uv-10","type":"riesgo","description":"Brotes de enfermedad respiratoria en pacientes y colaboradores por incumplimiento de protocolo (PR-UV-23)","cause":"Renuencia de médicos y familiares a aceptar el protocolo, no respeto del aislamiento de vía aérea","effect":"Brotes de enfermedad respiratoria, impacto en la capacidad operativa del hospital","probability":2,"impact":5,"action_plan":"Respaldo de dirección médica y dirección general para que se cumpla lo establecido. Supervisión del protocolo de aislamiento establecido.","responsible":"Responsable UVEH","due_date":"2025-11-30","status":"en_control"},
  {"id":"uv-11","type":"riesgo","description":"Infecciones en pacientes y colaboradores por mal ejecución de procesos en hemodiálisis (PCI.14 / PR-UV-22)","cause":"Falta de conocimientos en el manejo de pacientes de hemodiálisis, mala calidad del agua","effect":"Intoxicaciones, infecciones graves, riesgo de muerte en pacientes de hemodiálisis","probability":2,"impact":5,"action_plan":"Capacitación obligatoria de 3 semanas a cargo de la jefatura de enseñanza de enfermería. Supervisión continua de los niveles de cloración del agua y corrección en caso de desviaciones.","responsible":"Jefatura de Enfermería","due_date":"2025-11-30","status":"en_control"}
]'),

-- ── 2b. Nutrición y Dietética ─────────────────────────────────────
('Nutrición y Dietética', 'apoyo',
 'Jefe de Nutrición y Dietética',
 'Requisición de alimentos, identificación de errores de indicación médica en dietas, entrega de charolas y recolección, valoración nutricional del paciente hospitalizado.',
 17,
'[
  {"id":"nu-01","type":"riesgo","description":"Omisión de alergias o enfermedades relevantes que pueden desencadenar reacciones adversas graves (PR-NU-04)","cause":"Indicación médica incompleta, falta de comunicación entre el médico y el servicio de nutrición","effect":"Reacción alérgica grave, broncoaspiración, complicaciones en el paciente","probability":2,"impact":5,"action_plan":"Evaluación nutricional y preguntas por parte del personal de dietas. Revisión de indicación médica antes de preparar la dieta.","responsible":"Jefe de Nutrición","due_date":"2025-11-30","status":"en_control"},
  {"id":"nu-02","type":"riesgo","description":"Consistencia inadecuada de los alimentos que puede generar disfagia o broncoaspiración (PR-NU-04)","cause":"Error en la preparación de la dieta, falta de comunicación de la consistencia indicada","effect":"Broncoaspiración, neumonía por aspiración, riesgo de muerte","probability":2,"impact":3,"action_plan":"Verificación de la consistencia indicada en la dieta antes de la entrega. Capacitación del personal de cocina.","responsible":"Jefe de Nutrición","due_date":"2025-11-30","status":"en_control"},
  {"id":"nu-03","type":"riesgo","description":"Interacciones fármaco-nutrientes no identificadas (PR-NU-04)","cause":"Falta de comunicación entre farmacia, médico y nutrición","effect":"Reducción de la eficacia del medicamento o aumento de efectos adversos","probability":2,"impact":3,"action_plan":"Revisión de las interacciones fármaco-nutrientes al momento de indicar la dieta. Coordinación entre farmacia y nutrición.","responsible":"Jefe de Nutrición","due_date":"2025-12-31","status":"identificado"},
  {"id":"nu-04","type":"riesgo","description":"Contaminación cruzada entre pacientes en la entrega de dietas (PR-NU-13)","cause":"Manejo inadecuado de charolas y alimentos, falta de higiene en la distribución","effect":"Transmisión de enfermedades infecciosas entre pacientes","probability":2,"impact":4,"action_plan":"Lavado de manos constante y adecuado. Limpieza y desinfección del área de trabajo e instrumentos. Uso correcto y adecuado del equipo de protección.","responsible":"Jefe de Nutrición","due_date":"2025-11-30","status":"en_control"},
  {"id":"nu-05","type":"riesgo","description":"Malnutrición hospitalaria no identificada ni tratada oportunamente (PR-NU-14)","cause":"Falta de valoración nutricional al ingreso y seguimiento durante la estancia","effect":"Inmunocompromiso, mayor tiempo de estancia intrahospitalaria, aumento del tiempo de recuperación","probability":3,"impact":4,"action_plan":"Realizar el proceso de valoración nutricional de manera óptima y adecuada. Seguimiento continuo del estado nutricional del paciente.","responsible":"Jefe de Nutrición","due_date":"2025-11-30","status":"en_control"},
  {"id":"nu-06","type":"riesgo","description":"Desabasto de alimentos para pacientes (PR-NU-01)","cause":"Falta de requisición semanal oportuna de productos","effect":"Imposibilidad de cumplir con las dietas indicadas, insatisfacción del paciente","probability":2,"impact":3,"action_plan":"Requisición semanal de producto de manera oportuna.","responsible":"Jefe de Nutrición","due_date":"2025-12-31","status":"en_control"}
]'),

