  {"id":"re-02","type":"riesgo","description":"Tratamiento incorrecto por falta de verificación de indicaciones médicas (PR-RE-01/02/03/04)","cause":"No verificar las indicaciones y tratamientos prescritos por el médico","effect":"Daño al paciente, mala evolución clínica","probability":2,"impact":4,"action_plan":"Verificación de indicaciones y tratamientos antes de cada sesión.","responsible":"Jefe de Rehabilitación","due_date":"2025-11-30","status":"en_control"},
  {"id":"re-03","type":"riesgo","description":"Quemaduras al paciente por tipo de corrientes en electroterapia (PR-RE-01)","cause":"Revisión constante insuficiente en la aplicación de electroestímulos","effect":"Quemaduras superficiales o profundas, daño al paciente","probability":2,"impact":4,"action_plan":"Revisión constante en aplicación de electroestímulos. Nivelar la frecuencia del electroestimulador evitando que llegue a niveles altos.","responsible":"Jefe de Rehabilitación","due_date":"2025-11-30","status":"en_control"},
  {"id":"re-04","type":"riesgo","description":"Lesiones por mala ejecución del ejercicio en mecanoterapia (PR-RE-02)","cause":"Técnica incorrecta en la ejecución de los ejercicios","effect":"Lesiones musculoesqueléticas del paciente","probability":2,"impact":3,"action_plan":"Revisión constante durante la realización de los ejercicios. Enseñanza al paciente y familiares sobre la manera correcta de realizar los ejercicios en casa.","responsible":"Jefe de Rehabilitación","due_date":"2025-11-30","status":"en_control"},
  {"id":"re-05","type":"riesgo","description":"Caídas de pacientes por piso mojado en hidroterapia (PR-RE-04)","cause":"Falta de señalamiento y franjas antiderrapantes en el área de hidroterapia","effect":"Caídas con lesiones, prolongación de la estancia, responsabilidad legal","probability":3,"impact":3,"action_plan":"Evitar riesgo de caídas utilizando franjas antiderrapantes y señalamientos de piso mojado.","responsible":"Jefe de Rehabilitación","due_date":"2025-11-15","status":"en_control"},
  {"id":"re-06","type":"riesgo","description":"Olvidar pacientes en las tinas durante el tratamiento de hidroterapia (PR-RE-04)","cause":"Falta de vigilancia constante durante el tratamiento","effect":"Riesgo de ahogamiento, hipotermia o quemaduras, evento adverso grave","probability":1,"impact":5,"action_plan":"Vigilancia constante al tiempo de la ejecución del tratamiento muscular. No dejar sin supervisión a los pacientes en las tinas.","responsible":"Jefe de Rehabilitación","due_date":"2025-11-15","status":"en_control"},
  {"id":"re-07","type":"riesgo","description":"Actividades de terapia ocupacional realizadas de manera incorrecta (PR-RE-03)","cause":"Falta de capacitación o supervisión en las actividades asignadas","effect":"Mala evolución del paciente, frustración, posible lesión","probability":2,"impact":3,"action_plan":"Monitoreo de las actividades asignadas enseñando a los pacientes y familiares.","responsible":"Jefe de Rehabilitación","due_date":"2025-12-31","status":"en_control"}
]'),

