-- ── 2f. Banco de Sangre ───────────────────────────────────────────
('Banco de Sangre', 'misional',
 'Jefe de Banco de Sangre',
 'Instrucciones de trabajo de hemoclasificación, determinación de subgrupos, rastreo e identificación de anticuerpos irregulares, pruebas de compatibilidad, control de calidad de hemocomponentes y determinación de autocontrol.',
 21,
'[
  {"id":"bs-01","type":"riesgo","description":"Confusión de tubos de ensayo o pocillos en pruebas de compatibilidad mayor/menor (IT-BS-14/15)","cause":"Falta de rotulado previo de los tubos y pocillos antes del uso","effect":"Transfusión incompatible, reacción transfusional grave, riesgo de muerte","probability":2,"impact":5,"action_plan":"Rotulado previo de tubos y pocillos antes del uso en todas las pruebas. Doble verificación antes de la transfusión.","responsible":"Jefe de Banco de Sangre","due_date":"2025-11-15","status":"en_control"},
  {"id":"bs-02","type":"riesgo","description":"Contaminación biológico-infecciosa del operario durante cualquier procedimiento de Banco de Sangre (IT-BS-08/10/11/14/15/18)","cause":"No uso de guantes y EPP durante las instrucciones de trabajo","effect":"Accidente biológico, transmisión de enfermedades infecciosas al operario","probability":2,"impact":4,"action_plan":"Uso obligatorio de guantes y EPP durante todas las instrucciones de trabajo de Banco de Sangre.","responsible":"Jefe de Banco de Sangre","due_date":"2025-11-15","status":"en_control"},
  {"id":"bs-03","type":"riesgo","description":"Lectura errónea de los patrones de aglutinación (IT-BS-08/10/11/14/15/18)","cause":"Iluminación insuficiente, falta de imagen de referencia en el área de lectura","effect":"Clasificación incorrecta de grupo sanguíneo o anticuerpos, error diagnóstico con consecuencias graves","probability":2,"impact":5,"action_plan":"Imagen de referencia en el área de inmuno-hematología y luz clara para la lectura. Buena iluminación en el área de lectura.","responsible":"Jefe de Banco de Sangre","due_date":"2025-11-15","status":"en_control"},
